-- MP-0045: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0045: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0045: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('hishammuddin-hussein','muhammad-islahuddin-abas','manndzri-nasib') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0045: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('sembrong','mersing','tenggara') and slug not in ('hishammuddin-hussein','muhammad-islahuddin-abas','manndzri-nasib')) then raise exception 'MP-0045: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0045:%' and (m.source_type <> 'editorial' or e.slug not in ('hishammuddin-hussein','muhammad-islahuddin-abas','manndzri-nasib') or m.import_key not like 'MP-0045:' || e.slug || ':%')) then raise exception 'MP-0045: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'hishammuddin-hussein','Hishammuddin Hussein','government','Member of the Dewan Rakyat','Sembrong','Johor','Hishammuddin Hussein represents Sembrong, Johor, in the Dewan Rakyat. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4192','/portraits/hishammuddin-hussein.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P153.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4192"}, {"label": "UMNO · suspension lifted, 17 April 2026", "url": "https://www.freemalaysiatoday.com/category/nation/2026/04/17/khairy-back-in-umno"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'muhammad-islahuddin-abas','Muhammad Islahuddin Abas','opposition','Member of the Dewan Rakyat','Mersing','Johor','Muhammad Islahuddin Abas represents Mersing, Johor, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4193','/portraits/muhammad-islahuddin-abas.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P154.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4193"}, {"label": "PN campaigning and Bersatu suspension · 3 July 2026", "url": "https://www.malaysiakini.com/news/778808"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'manndzri-nasib','Manndzri Nasib','government','Member of the Dewan Rakyat','Tenggara','Johor','Manndzri Nasib represents Tenggara, Johor, in the Dewan Rakyat. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4194','/portraits/manndzri-nasib.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P155.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4194"}, {"label": "UMNO · current representative, 4 September 2026", "url": "https://umno-online.my/2026/09/04/umno-perlu-terus-bangkit-usaha-baiki-amanah-rakyat-manndzri/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('hishammuddin-hussein','muhammad-islahuddin-abas','manndzri-nasib') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0045: concurrent ownership or identity change'; end if; end $$;

commit;
